/** Должно совпадать с медиазапросом скрытия `.minimizedChats` в ChatFooter.module.scss */
const CHAT_COMPACT_MINIMIZED_QUERY = '(max-width: 1024px)';

/** Геометрия `.chatFooter` / `ChatFooterResizableRoot`: превью левее развёрнутого окна с зазором. */
const CHAT_FOOTER_RIGHT = 80;
const CHAT_FOOTER_BOTTOM = 80;

function defaultDockMargins(isOperatorChatPopup: boolean): { r: number; b: number } {
  if (isOperatorChatPopup) {
    return {
      r: OPERATOR_CHAT_POPUP_DOCK_EDGE_MARGIN_PX,
      b: OPERATOR_CHAT_POPUP_DOCK_EDGE_MARGIN_PX,
    };
  }
  return { r: CHAT_FOOTER_RIGHT, b: CHAT_FOOTER_BOTTOM };
}
const MINIMIZED_PREVIEW_GAP_PX = 28;
const DEFAULT_CHAT_PANEL: ChatFooterPanelSize = { w: 520, h: 660 };
const MIN_CHAT_PANEL: ChatFooterPanelSize = { w: 360, h: 320 };
const PANEL_VIEW_MARGIN_PX = 40;
/** Минимальная полоска dock остаётся в окне при перетаскивании (в т.ч. к краю второго монитора в широком окне). */
const DOCK_VISIBILITY_STRIP_PX = 48;
const DOCK_PREVIEW_ROW_APPROX_PX = 68;
/** Колонка FAB (+ и переключатель чата) справа от панели внутри dock */
const DOCK_FAB_COLUMN_W_PX = 56;
const DOCK_FAB_STACK_H_PX = 196;

function readSavedPanelSize(isOperatorChatPopup: boolean): ChatFooterPanelSize | null {
  if (typeof window === 'undefined') return null;
  const k = chatPanelDockStorageKeys(isOperatorChatPopup);
  try {
    const w = parseInt(localStorage.getItem(k.panelW) || '', 10);
    const h = parseInt(localStorage.getItem(k.panelH) || '', 10);
    if (!Number.isFinite(w) || !Number.isFinite(h)) return null;
    return { w, h };
  } catch {
    return null;
  }
}

function readSavedDockMargins(isOperatorChatPopup: boolean): { r: number; b: number } | null {
  if (typeof window === 'undefined') return null;
  const k = chatPanelDockStorageKeys(isOperatorChatPopup);
  try {
    const r = parseInt(localStorage.getItem(k.dockR) || '', 10);
    const b = parseInt(localStorage.getItem(k.dockB) || '', 10);
    if (!Number.isFinite(r) || !Number.isFinite(b)) return null;
    return { r, b };
  } catch {
    return null;
  }
}

function readInitialDockMargins(isOperatorChatPopup: boolean): { r: number; b: number } {
  const defaults = defaultDockMargins(isOperatorChatPopup);
  const saved = readSavedDockMargins(isOperatorChatPopup);
  if (saved) {
    return saved;
  }
  return defaults;
}

/** Желаемый размер панели (default / LS / ручной ресайз), без автоклампа по viewport. */
function readDesiredPanelSize(isOperatorChatPopup: boolean): ChatFooterPanelSize {
  if (typeof window === 'undefined') {
    return { ...DEFAULT_CHAT_PANEL };
  }
  const isPopupPath = window.location.pathname === RoutePaths.operatorChatPopup;
  if (isPopupPath && isBrowserWebChatShell()) {
    return { w: POPUP_DOCK_PANEL_W_PX, h: POPUP_DOCK_PANEL_H_PX };
  }
  const saved = readSavedPanelSize(isOperatorChatPopup);
  if (saved) {
    return {
      w: Math.max(MIN_CHAT_PANEL.w, saved.w),
      h: Math.max(MIN_CHAT_PANEL.h, saved.h),
    };
  }
  return { ...DEFAULT_CHAT_PANEL };
}

function clampPanelSize(size: ChatFooterPanelSize): ChatFooterPanelSize {
  if (typeof window === 'undefined') return size;
  const { width: vw, height: vh } = getLayoutViewportSize();
  const maxW = Math.max(MIN_CHAT_PANEL.w, vw - CHAT_FOOTER_RIGHT - PANEL_VIEW_MARGIN_PX);
  const maxH = Math.max(MIN_CHAT_PANEL.h, vh - CHAT_FOOTER_BOTTOM - PANEL_VIEW_MARGIN_PX);
  return {
    w: Math.min(maxW, Math.max(MIN_CHAT_PANEL.w, size.w)),
    h: Math.min(maxH, Math.max(MIN_CHAT_PANEL.h, size.h)),
  };
}

/** Ширина `.chatFloatingDock` без колонки развёрнутых панелей: FAB + 2×gap + опционально колонка превью. */
function dockNonPanelWidthPx(previewCount: number): number {
  const previewColW = previewCount > 0 ? 260 : 0;
  return DOCK_FAB_COLUMN_W_PX + 2 * MINIMIZED_PREVIEW_GAP_PX + previewColW;
}

function clampPanelSizeForFloatingDock(
  size: ChatFooterPanelSize,
  args: {
    previewCount: number;
    expandedCount: number;
    dockRightPx: number;
    dockBottomPx: number;
  },
): ChatFooterPanelSize {
  if (typeof window === 'undefined') return size;
  const { width: vw, height: vh } = getLayoutViewportSize();
  const { previewCount, expandedCount, dockRightPx, dockBottomPx } = args;
  const nonPanelW = dockNonPanelWidthPx(previewCount);
  const maxW = Math.max(MIN_CHAT_PANEL.w, vw - dockRightPx - PANEL_VIEW_MARGIN_PX - nonPanelW);

  const maxDockH = Math.max(MIN_CHAT_PANEL.h, vh - dockBottomPx - PANEL_VIEW_MARGIN_PX);
  const previewStackH =
    previewCount > 0 ? previewCount * DOCK_PREVIEW_ROW_APPROX_PX + (previewCount - 1) * 8 : 0;

  let maxH = maxDockH;
  if (expandedCount > 0) {
    const sideColumnsH = Math.max(DOCK_FAB_STACK_H_PX, previewStackH);
    if (sideColumnsH <= maxDockH) {
      const maxFromPanels = (maxDockH - (expandedCount - 1) * 8) / expandedCount;
      maxH = Math.max(MIN_CHAT_PANEL.h, Math.floor(maxFromPanels));
    }
  }

  return {
    w: Math.min(maxW, Math.max(MIN_CHAT_PANEL.w, size.w)),
    h: Math.min(maxH, Math.max(MIN_CHAT_PANEL.h, size.h)),
  };
}

function getMaxPanelSizeForFloatingDock(args: {
  previewCount: number;
  expandedCount: number;
  dockRightPx: number;
  dockBottomPx: number;
}): ChatFooterPanelSize {
  if (typeof window === 'undefined') return { ...DEFAULT_CHAT_PANEL };
  return clampPanelSizeForFloatingDock({ w: 100000, h: 100000 }, args);
}

function clampDockMargins(
  r: number,
  b: number,
  dockW: number,
  dockH: number,
): { r: number; b: number } {
  if (typeof window === 'undefined') return { r, b };
  const { width: vw, height: vh } = getLayoutViewportSize();
  const strip = DOCK_VISIBILITY_STRIP_PX;
  const maxR = vw - strip;
  const maxB = vh - strip;
  const minR = -dockW + strip;
  const minB = -dockH + strip;
  return {
    r: Math.min(maxR, Math.max(minR, r)),
    b: Math.min(maxB, Math.max(minB, b)),
  };
}

function normalizeSessionDialogId(raw: unknown): number | null {
  if (raw === undefined || raw === null || raw === 'assigned') return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

function hasRenderableMinimizedContent(session: {
  selectedUsers?: unknown[];
  selectedUserName?: unknown;
  selectedDialog?: { id?: unknown } | null;
  assignedDialogId?: unknown;
  messages?: unknown[];
}): boolean {
  const hasSelectedUser = (session.selectedUsers?.length ?? 0) > 0;
  const hasSelectedUserName = typeof session.selectedUserName === 'string' && session.selectedUserName.trim() !== '';
  const selectedDialogId = session.selectedDialog?.id;
  const hasSelectedDialogId = Boolean(
    selectedDialogId != null &&
      String(selectedDialogId) !== '' &&
      String(selectedDialogId) !== '0' &&
      String(selectedDialogId) !== 'assigned',
  );
  const assignedDialogId = session.assignedDialogId;
  const hasAssignedDialogId = Boolean(
    assignedDialogId != null &&
      String(assignedDialogId) !== '' &&
      String(assignedDialogId) !== '0' &&
      String(assignedDialogId) !== 'assigned',
  );
  const hasMessages = (session.messages?.length ?? 0) > 0;
  return hasSelectedUser || hasSelectedUserName || hasSelectedDialogId || hasAssignedDialogId || hasMessages;
}

/** Боковое превью — только сессии с конкретным пользователем (не «Новый чат»). */
function hasConcreteUserForSidePreview(session: {
  selectedUsers?: unknown[];
  selectedUserName?: unknown;
  selectedDialog?: { client_name?: unknown; clientName?: unknown } | null;
}): boolean {
  const hasSelectedUserName =
    typeof session.selectedUserName === 'string' && session.selectedUserName.trim() !== '';
  const clientName = session.selectedDialog?.client_name ?? session.selectedDialog?.clientName;
  const hasClientName = typeof clientName === 'string' && clientName.trim() !== '';
  const hasSelectedUser = (session.selectedUsers?.length ?? 0) > 0;
  return hasSelectedUserName || hasClientName || hasSelectedUser;
}

function shouldShowSessionInSidePreview(session: {
  selectedUsers?: unknown[];
  selectedUserName?: unknown;
  selectedDialog?: {
    id?: unknown;
    client_name?: unknown;
    clientName?: unknown;
    status?: unknown;
    lastOperator?: { id?: unknown } | null;
    last_operator?: { id?: unknown } | null;
  } | null;
  assignedDialogId?: unknown;
  messages?: unknown[];
  isMinimized?: boolean;
  usersCache?: Map<unknown, unknown>;
}): boolean {
  if (!sessionBelongsToCurrentOperatorBranch(session)) return false;
  if (isSessionClosedClaimedByOtherOperator(session)) return false;
  return hasRenderableMinimizedContent(session) && hasConcreteUserForSidePreview(session);
}

/** Диалог уже открыт/привязан к какой‑либо сессии — не показывать его второй раз в превью «непрочитанных». */
function sessionListAlreadyCoversDialog(
  sessions: Array<{ selectedDialog?: { id?: unknown }; assignedDialogId?: unknown }>,
  dialogId: number,
): boolean {
  return sessions.some((session) => {
    const fromSelected = normalizeSessionDialogId(session.selectedDialog?.id);
    const fromAssigned = normalizeSessionDialogId(session.assignedDialogId);
    return fromSelected === dialogId || fromAssigned === dialogId;
  });
}

/**
 * Список непрочитанных с API кладётся в unreadDialogs у каждой сессии (loadUnreadDialogs).
 * Без дедупликации один dialog.id даёт по строке превью на каждую сессию — на мобильном список и счётчик врут.
 */
function collectDedupedUnreadDialogsForPreview(
  sessions: Array<{
    id: string;
    isMinimized?: boolean;
    unreadDialogs?: UnreadDialog[];
    selectedDialog?: { id?: unknown };
    assignedDialogId?: unknown;
  }>,
  hasSessionWithUser: (userId: number) => boolean,
): { dialog: UnreadDialog; sessionId: string }[] {
  const seenDialogIds = new Set<number>();
  const rows: { dialog: UnreadDialog; sessionId: string }[] = [];

  const orderedSessions = [...sessions].sort((a, b) => {
    const ma = !!a.isMinimized;
    const mb = !!b.isMinimized;
    if (ma === mb) return 0;
    return ma ? 1 : -1;
  });

  for (const session of orderedSessions) {
    const unreadList =
      session.unreadDialogs?.filter((dialog) => {
        if (!isPayloadForCurrentOperatorBranch(dialog)) return false;
        if (isCurrentOperatorUser(dialog.owner?.id)) return false;
        if (!isClosedDialogVisibleToCurrentOperator(dialog)) return false;
        const dialogUserId = dialog.owner?.id;
        if (dialogUserId && hasSessionWithUser(dialogUserId)) return false;
        if (sessionListAlreadyCoversDialog(sessions, dialog.id)) return false;
        return true;
      }) ?? [];

    for (const dialog of unreadList) {
      if (seenDialogIds.has(dialog.id)) continue;
      const coveredByExpanded = sessions.some(
        (s) =>
          !s.isMinimized &&
          (normalizeSessionDialogId(s.selectedDialog?.id) === dialog.id ||
            normalizeSessionDialogId(s.assignedDialogId) === dialog.id),
      );
      if (coveredByExpanded) continue;
      seenDialogIds.add(dialog.id);
      rows.push({ dialog, sessionId: session.id });
    }
  }

  return rows;
}

function previewLineFromMessagePayload(msg: unknown, attachmentLabel: string): string {
  if (!msg || typeof msg !== 'object') return '';
  const m = msg as { text?: string; attachments?: unknown[] };
  const text = (m.text || '').trim();
  if (text.length > 0) return text;
  if (Array.isArray(m.attachments) && m.attachments.length > 0) return attachmentLabel;
  return '';
}

function truncatePreviewLine(text: string, maxLen: number): string {
  const s = text.trim();
  if (!s) return '';
  return s.length <= maxLen ? s : `${s.slice(0, maxLen)}…`;
}

/** Сравнение id филиала из zustand (number | string) без ложных «смен» при 5 vs "5". */
function normalizeBranchIdForChatClear(raw: unknown): string | null {
  if (raw === undefined || raw === null || raw === '') return null;
  return String(raw);
}

function unreadCountForPreviewEntry(
  dialog: UnreadDialog,
  dialogsUnreadCounts: Map<number, number> | undefined,
): number {
  // Бейдж превью: первоисточник — WS-карта (/user/queue/unread и per-dialog строки
  // /queue/unread/{branch}). Если WS-записи для диалога ещё нет (кадр филиала бывает
  // неполным, а превью уже отрендерено по REST-списку) — seed из REST-списка.
  // Как только WS пришлёт значение (в т.ч. 0), оно станет единственным.
  const map = dialogsUnreadCounts || new Map();
  const wsValue = map.get(dialog.id);
  if (wsValue !== undefined) return wsValue;
  const fromApi = Number(dialog.countUnMessages ?? dialog.countUnreadMess ?? 0);
  return Number.isFinite(fromApi) && fromApi > 0 ? fromApi : 0;
}

/**
 * Счётчик на превью свёрнутой сессии: единственный источник — WS-карта dialogsUnreadCounts
 * (наполняется подпиской /user/queue/unread). Никаких REST-значений и session.unreadCount.
 */
function effectiveMinimizedSessionUnread(
  session: {
    selectedDialog?: { id?: unknown };
    assignedDialogId?: unknown;
  },
  dialogsUnreadCounts: Map<number, number> | undefined,
): number {
  const dialogId = resolveSessionDialogIdForUnread(session);
  if (dialogId == null || !dialogsUnreadCounts) return 0;
  return dialogsUnreadCounts.get(dialogId) ?? 0;
}

function unreadInSessionMessagesByDialog(
  session: { messages?: any[] } | undefined,
  dialogId: number,
): number {
  if (!session?.messages?.length) return 0;
  return session.messages.reduce((acc: number, msg: any) => {
    const mid = Number(msg.dialogId ?? msg.dialog?.id ?? NaN);
    if (mid !== Number(dialogId)) return acc;
    if (msg.messageStatus !== 'TO_OPERATOR') return acc;
    if (msg.is_read) return acc;
    if (String(msg.confirmStatus ?? '').toUpperCase() === 'READ') return acc;
    return acc + 1;
  }, 0);
}

function minimizedSessionPreviewRaw(
  session: {
    messages?: any[];
    selectedDialog?: { id?: unknown };
    assignedDialogId?: unknown;
  },
  fetchedByDialogId: Record<number, string>,
  attachmentLabel: string,
): string {
  if (session.messages?.length) {
    const last = session.messages[session.messages.length - 1];
    const local = previewLineFromMessagePayload(last, attachmentLabel);
    if (local) return local;
  }
  const did = normalizeSessionDialogId(session.selectedDialog?.id ?? session.assignedDialogId);
  if (did !== null) {
    const fetched = (fetchedByDialogId[did] || '').trim();
    if (fetched) return fetched;
  }
  return '';
}

function unreadCountFromDialogRecord(dialog: UnreadDialog | Record<string, unknown>): number {
  const rec = dialog as Record<string, unknown>;
  const preferred = [
    rec.countUnMessages,
    rec.countUnreadMess,
    rec.countMessages,
    rec.countUnreadMessages,
    rec.unreadCount,
    rec.unread,
  ];
  for (const value of preferred) {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  for (const [key, value] of Object.entries(rec)) {
    if (typeof value !== 'number' && typeof value !== 'string') continue;
    if (!/count|unread/i.test(key)) continue;
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return 0;
}

function sumUnreadDialogCounts(dialogs: UnreadDialog[]): number {
  return (dialogs || []).reduce((acc, dialog) => acc + unreadCountFromDialogRecord(dialog), 0);
}

/**
 * Allowlist бейджа иконки при закрытом окне — та же развилка, что у ChatPanel
 * (чужой CLOSED → exclude, иначе include) после loadDialogDetails при открытом окне.
 */
function applyClosedChatIconAllowlistFromDialog(
  dialogLike: any,
  includeFn: (dialogId: number) => void,
  excludeFn: (dialogId: number) => void,
) {
  const id = Number(dialogLike?.dialogId ?? dialogLike?.id ?? dialogLike?.dialog?.id);
  if (!(id > 0)) return;
  const status = String(
    dialogLike?.dialogStatus ?? dialogLike?.status ?? dialogLike?.dialog?.status ?? '',
  ).toUpperCase();
  if (!status) return;

  const forVisibility = {
    status,
    lastOperator:
      dialogLike?.lastOperator ??
      dialogLike?.last_operator ??
      dialogLike?.dialog?.lastOperator ??
      dialogLike?.dialog?.last_operator ??
      null,
  };

  if (status !== 'CLOSED') {
    includeFn(id);
    return;
  }
  if (!isClosedDialogVisibleToCurrentOperator(forVisibility)) {
    excludeFn(id);
  }
}

